for(const[a,v]of Object.entries(race.bonuses))bonuses[a]=(bonuses[a]||0)+v;if(sel.subrace&&race.subraces&&race.subraces[sel.subrace]){for(const[a,v]of Object.entries(race.subraces[sel.subrace].bonuses))bonuses[a]=(bonuses[a]||0)+v;}
