html+=`<div class="detail-row"><b>♻️ Descanso Curto:</b> ${RECOVERY_PT[c.rec]}</div></div>`;if(stats){html+=`<div class="detail-section collapsed"><div class="detail-section-title section-toggle" onclick="toggleSection(this)">📊 Atributos${sel.race ? ' (com bônus de ' + RACES[sel.race].name + ')' : ''}<span class="toggle-arrow">▾</span></div><div class="section-body">`;attrs.forEach(a=>{const v=stats[a];const m=mod(v);const sign=m>=0?'+':'';const baseV=baseStats[a];const raceBonus=v-baseV;const pct=Math.min(100,(v/20)*100);html+=`<div style="margin-bottom:6px"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:2px"><span style="color:var(--v-text-dim)">${ATTR_PT[a]}</span><span><b style="color:var(--v-text-bright)">${v}</b> <span style="color:${m >= 0 ? 'var(--v-success)' : 'var(--v-danger)'}; font-size:11px">(${sign}${m})</span>${raceBonus > 0 ? `<span style="color:var(--v-gold);font-size:10px">+${raceBonus}raça</span>` : ''}</span></div>`;html+=`<div class="stat-bar-track"><div class="stat-bar-fill" style="width:${pct}%"></div></div></div>`;});html+=`</div></div>`;}
