async function checkAndShowL1Skills(){if(!sel.classKey||!apiBase){finishClassScreen();return;}
if(_l1SkillsCache[sel.classKey]){const data=_l1SkillsCache[sel.classKey];if(data.skills&&data.skills.length>0){buildL1SkillSelect(data);openSubScreen('sub-l1skill-select');return;}
finishClassScreen();return;}
try{const _ac1=new AbortController();const _tid1=setTimeout(()=>_ac1.abort(),10000)/*_TIMEOUT*/;const resp=await fetch(`${apiBase}/api/character/l1-skills?class=${sel.classKey}`,{headers:{},signal:_ac1.signal,});clearTimeout(_tid1);if(!resp.ok){finishClassScreen();return;}
const data=await resp.json();_l1SkillsCache[sel.classKey]=data;if(data.skills&&data.skills.length>0){buildL1SkillSelect(data);openSubScreen('sub-l1skill-select');return;}}catch(e){console.warn('[CHAR_CREATOR] L1 skills fetch failed',e);}
finishClassScreen();}
function buildL1SkillSelect(data){const defaultSkill=data.default||'';const choices=data.skills.filter(s=>!s.is_default);let html=`<button class="v-btn v-btn-secondary v-btn-pill sub-back" onclick="cancelL1Skill()">\u2190 Voltar</button>`;html+=`<div class="detail-header"><div class="detail-title">\u2728 Escolha uma Habilidade</div>`;html+=`<div class="detail-subtitle">Sua classe começa com <b>${data.skills.find(s => s.is_default)?.name || 'habilidade padrão'}</b>. Escolha mais uma:</div></div>`;for(const skill of choices){const selected=sel.selectedL1Skill===skill.id?' selected':'';const costText=skill.cost>0?` \u2022 ${skill.cost} MP`:'';html+=`<div class="v-card${selected}" onclick="selectL1Skill('${skill.id}')">`;html+=`<div class="v-card-name">${skill.effect || ''} ${skill.name}</div>`;html+=`<div class="v-card-desc">${skill.description}${costText}</div>`;html+=`</div>`;}
document.getElementById('l1skillSelectContent').innerHTML=html;}
